import { StyleSheet } from 'react-native';
import { spacing } from '../theme';

export default StyleSheet.create({
  container: {
    padding: spacing.lg,
    borderRadius: 28,
    marginBottom: spacing.lg,
    borderWidth: 1,
    borderColor: 'rgba(255,255,255,0.08)',
    shadowColor: '#00D4FF',
    shadowOffset: { width: 0, height: 12 },
    shadowOpacity: 0.18,
    shadowRadius: 24,
    elevation: 6,
    overflow: 'hidden',
  },
  title: {
    color: '#FFFFFF',
    fontSize: 26,
    fontWeight: '800',
    letterSpacing: 0.2,
  },
  subtitle: {
    color: '#E3EEFF',
    fontSize: 13,
    lineHeight: 18,
    marginTop: spacing.xs,
  },
});
